"""Render the human-readable release document from the packaged manifest; no app import."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / 'static/release-notes.json'
OUTPUT = ROOT / 'docs/RELEASE_NOTES.md'


def render(releases):
    lines = ['# Inventory Portal release notes', '',
             'Generated from [the packaged release manifest](../static/release-notes.json).',
             'Update that manifest and run `python3 scripts/render_release_notes.py`; do not edit this file by hand.', '',
             'Build 1 starts explicit application build numbering. Earlier releases had no displayed',
             'build number and are identified by their application commit. Entries describe source',
             'contents, not proof of deployment; see [deployment history](DEPLOYMENTS.md) for verified releases.', '']
    for release in releases:
        label = ('Build '+str(release['build_number']) if release['build_number'] is not None
                 else 'Legacy build '+release['commit'])
        lines += ['## '+label+' — '+release['title'], '', 'Date: '+release['date'], '']
        if release['commit']:
            lines += ['Application commit: [`'+release['commit']+'`](https://github.com/vivraji/inventory-portal/commit/'+release['commit']+')', '']
        lines += ['- '+change for change in release['changes']]
        lines += ['']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = render(json.loads(MANIFEST.read_text()))
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text()!=expected:
            raise SystemExit('Release notes are stale; run python3 scripts/render_release_notes.py')
        print('Release notes match packaged manifest')
    else:
        OUTPUT.write_text(expected)
        print('Updated docs/RELEASE_NOTES.md')


if __name__ == '__main__':
    main()
